import { useState } from "react";
import { useTranslation } from "react-i18next";

import {
  getAuth,
  signInWithPopup,
  GoogleAuthProvider,
  createUserWithEmailAndPassword,
  sendEmailVerification,
  updateProfile,
  fetchSignInMethodsForEmail,
} from "firebase/auth";
import {
  getFirestore,
  doc,
  setDoc,
  getDoc,
  serverTimestamp,
} from "firebase/firestore";
import { useNavigate } from "react-router-dom";

import { Link } from "react-router-dom";
import { auth, db } from "../../config/firebase";
import ImageSlider from "../UI/ImageSlider";
import logoHCC_AI from "../../assets/images/logo_hcc_ai.jpg";
import logoGoogle from "../../assets/images/logo_google.jpg";
import { FaEye, FaEyeSlash } from "react-icons/fa";

function Signup() {
  const auth = getAuth();
  const db = getFirestore();
  const navigate = useNavigate();
  const { t, i18n } = useTranslation("global");

  const [authing, setAuthing] = useState(false);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [accessCode, setAccessCode] = useState("");

  const [userName, setUserName] = useState("");
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [phone, setPhone] = useState("");
  const [error, setError] = useState("");
  const [verificationMessage, setVerificationMessage] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const defaultUsefulLinks = [
    {
      name: "EASL",
      url: "https://easl.eu/",
      icon: "data:image/png;base64,",
    },
    {
      name: "HRHortega",
      url: "https://www.saludcastillayleon.es/HRHortega/es",
      icon: "data:image/png;base64,",
    },
    {
      name: "HP SCDS",
      url: "https://hpscds.com/",
      icon: "data:image/png;base64,",
    },
  ];

  const defaultProfilePictureUrl =
    "https://firebasestorage.googleapis.com/v0/b/hcc-ai.firebasestorage.app/o/HCC-AI%2Fpublic%2Fdefault_logo_user.png?alt=media&token=499a8fd4-85dc-49be-8d4a-a469aea1d1f7";

  const signUpWithEmail = async () => {
    const validCodes = import.meta.env.VITE_ACCESS_CODE;

    if (!validCodes.includes(accessCode.trim())) {
      setError("El código de acceso es inválido.");
      setAuthing(false);
      return;
    }

    if (password !== confirmPassword) {
      setError("Las contraseñas no coinciden");
      return;
    }

    setAuthing(true);
    setError("");
    setVerificationMessage("");

    try {
      const userCredential = await createUserWithEmailAndPassword(
        auth,
        email,
        password,
      );
      const user = userCredential.user;

      await updateProfile(user, {
        displayName: userName,
        photoURL: defaultProfilePictureUrl,
      });

      await sendEmailVerification(user);
      const imageFolder = `HCC-AI/users/${user.uid}/images/`;
      const documentFolder = `HCC-AI/users/${user.uid}/documents/`;

      await setDoc(doc(db, "hcc_ai_users", user.uid), {
        userName: userName,
        firstName: firstName,
        lastName: lastName,
        email: user.email,
        phone: phone,
        profilePicture: defaultProfilePictureUrl,
        imageFolder: imageFolder,
        documentFolder: documentFolder,
        createdAt: serverTimestamp(),
        useful_links: defaultUsefulLinks,
      });

      setUserName("");
      setFirstName("");
      setLastName("");
      setEmail("");
      setPhone("");
      setPassword("");
      setConfirmPassword("");
      setAccessCode("");

      setVerificationMessage(
        "Registro exitoso. Por favor, verifica tu correo electrónico antes de iniciar sesión.",
      );
    } catch (error) {
      console.log(error);

      if ((error as any).code === "auth/email-already-in-use") {
        setError("Esta dirección de correo ya está registrada.");
      } else if ((error as any).code === "auth/weak-password") {
        setError("La contraseña debe tener al menos 6 caracteres.");
      } else {
        setError("Hubo un error en el registro. Inténtalo de nuevo.");
      }
    }

    setAuthing(false);
  };

  return (
    <div className="w-full h-screen flex">
      <div className="w-1/2 h-full flex flex-col bg-[#282c34]">
        <ImageSlider />
      </div>

      <div className="w-1/2 h-full bg-black flex flex-col p-20 justify-center">
        <div className="w-full flex flex-col max-w-[450px] mx-auto">
          <div className="w-full flex flex-col mb-10 text-white">
            <img
              src={logoHCC_AI}
              alt="Logo HCC-AI"
              className="w-80 rounded-md center mx-auto mb-10 cursor-pointer"
              onClick={() => navigate("/")}
            />
            <h3 className="text-4xl font-bold mb-2 text-center">
              {t("signup.title")}
            </h3>
            <p className="text-lg mb-4 text-center">{t("signup.subtitle")}</p>
          </div>

          <input
            type="text"
            placeholder={t("signup.username")}
            className="flex-1 text-white py-2 bg-transparent border-b border-gray-500 focus:outline-none focus:border-white mb-4"
            value={userName}
            onChange={(e) => setUserName(e.target.value)}
          />

          <div className="w-full flex flex-wrap gap-4 mb-6">
            <input
              type="text"
              placeholder={t("signup.firstname")}
              className="flex-1 text-white py-2 bg-transparent border-b border-gray-500 focus:outline-none focus:border-white"
              value={firstName}
              onChange={(e) => setFirstName(e.target.value)}
            />
            <input
              type="text"
              placeholder={t("signup.lastname")}
              className="flex-1 text-white py-2 bg-transparent border-b border-gray-500 focus:outline-none focus:border-white"
              value={lastName}
              onChange={(e) => setLastName(e.target.value)}
            />
          </div>

          <input
            type="email"
            placeholder={t("signup.email")}
            className="w-full text-white py-2 mb-4 bg-transparent border-b border-gray-500 focus:outline-none focus:border-white"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />

          <div className="w-full flex flex-wrap gap-4 mb-6">
            <div className="relative flex-1">
              <input
                type={showPassword ? "text" : "password"}
                placeholder={t("signup.password")}
                className="w-full text-white py-2 bg-transparent border-b border-gray-500 focus:outline-none focus:border-white pr-10"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
              <button
                type="button"
                className="absolute right-0 top-2 text-white"
                onClick={() => setShowPassword(!showPassword)}
              >
                {showPassword ? <FaEyeSlash /> : <FaEye />}
              </button>
            </div>

            <div className="relative flex-1">
              <input
                type={showConfirmPassword ? "text" : "password"}
                placeholder={t("signup.confirm_password")}
                className="w-full text-white py-2 bg-transparent border-b border-gray-500 focus:outline-none focus:border-white pr-10"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
              />
              <button
                type="button"
                className="absolute right-0 top-2 text-white"
                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
              >
                {showConfirmPassword ? <FaEyeSlash /> : <FaEye />}
              </button>
            </div>
          </div>

          <div className="w-full flex flex-wrap gap-4 mb-6">
            <input
              type="text"
              placeholder={t("signup.access_code")}
              className="flex-1 text-white py-2 bg-transparent border-b border-gray-500 focus:outline-none focus:border-white"
              value={accessCode}
              onChange={(e) => setAccessCode(e.target.value)}
            />

            <input
              type="text"
              placeholder={t("signup.phone")}
              className="flex-1 text-white py-2 bg-transparent border-b border-gray-500 focus:outline-none focus:border-white"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
            />
          </div>

          {error && <div className="text-red-500 mb-4">{error}</div>}

          {verificationMessage && (
            <div className="text-green-500 mb-4">{verificationMessage}</div>
          )}

          <div className="w-full flex flex-col mb-4">
            <button
              onClick={signUpWithEmail}
              disabled={authing}
              className="w-full bg-transparent border border-white text-white my-2 font-semibold rounded-md p-4 text-center flex items-center justify-center cursor-pointer"
            >
              {t("signup.button")}
            </button>
          </div>

          <div className="w-full flex items-center justify-center relative py-4">
            <div className="w-full h-[1px] bg-gray-500"></div>
            <p className="text-lg absolute text-gray-500 bg-black px-2">OR</p>
          </div>
        </div>

        <div className="w-full flex items-center justify-center mt-10">
          <p className="text-sm font-normal text-gray-400">
            {t("signup.have_account")}{" "}
            <span className="font-semibold text-white cursor-pointer underline">
              <Link to="/login">{t("signup.login_link")}</Link>
            </span>
          </p>
        </div>
      </div>
    </div>
  );
}

export default Signup;
